/** The host owns buffering and draining for this output's batch policy. */
const log = createLogHost({
  plugins: [
    levelPlugin(),
    filePlugin({ path: 'application.ndjson', writer, features: [batchFeature({ maxSize: 2 })] })
  ]
})
log.info('first')
log.info('second')
await log.flush()
